), release_versions(version) as (values ('20261125100000'),('20261125101000')),
recorded as materialized (select version::text as version from supabase_migrations.schema_migrations),
cohort_function as (
  select p.oid,p.prosecdef,p.provolatile,p.proconfig,p.proargnames,p.pronargdefaults,p.prorettype,
    p.proacl,p.proowner,case when p.oid is not null then pg_get_functiondef(p.oid) end as definition
  from (select to_regprocedure('public.production_policy_cohort(date,date,uuid)')::oid as oid) t
  left join pg_proc p on p.oid=t.oid
)
select jsonb_build_object(
  'base_sha','d0302b334f7264ed214f8aaca5d174ef3fc3fc63',
  'expected_base_count',(select count(*) from expected_base),
  'recorded_base_count',(select count(*) from expected_base e where exists(select 1 from recorded r where r.version=e.version)),
  'missing_base_versions',(select coalesce(jsonb_agg(e.version order by e.version),'[]'::jsonb) from expected_base e where not exists(select 1 from recorded r where r.version=e.version)),
  'new_migrations',(select jsonb_agg(jsonb_build_object('version',e.version,'recorded',exists(select 1 from recorded r where r.version=e.version)) order by e.version) from release_versions e),
  'application_functions_executed',false,
  'policy_cohort',(select jsonb_build_object(
    'present',f.oid is not null,
    'arguments',case when f.oid is not null then pg_get_function_arguments(f.oid) end,
    'jsonb_return',coalesce(f.prorettype='jsonb'::regtype,false),
    'argument_names_exact',coalesce(f.proargnames=array['p_start','p_end','p_agent_id']::text[],false),
    'one_default_argument',coalesce(f.pronargdefaults=1,false),
    'security_definer',coalesce(f.prosecdef,false),
    'stable',coalesce(f.provolatile='s',false),
    'public_search_path',coalesce(f.proconfig @> array['search_path=public']::text[],false),
    'authenticated_execute',case when f.oid is not null then has_function_privilege('authenticated',f.oid,'EXECUTE') else false end,
    'anon_execute',case when f.oid is not null then has_function_privilege('anon',f.oid,'EXECUTE') else false end,
    'public_execute',case when f.oid is not null then exists(select 1 from aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) a where a.grantee=0 and a.privilege_type='EXECUTE') else false end,
    'auth_guard',coalesce(position('auth.uid() is null' in f.definition)>0,false),
    'blocked_user_guard',coalesce(position('fn_user_login_blocked(auth.uid())' in f.definition)>0,false),
    'suspended_user_guard',coalesce(position('fn_user_is_suspended(auth.uid())' in f.definition)>0,false),
    'canonical_self_guard',coalesce(position('coalesce(a.canonical_agent_id,a.id)=v_target and a.user_id=auth.uid()' in f.definition)>0,false),
    'exact_site_link',coalesce(position('and p.site_deal_id=d.id' in f.definition)>0,false),
    'no_policy_number_inference',coalesce(position('fn_carrier_pn_key' in f.definition)=0 and position('submission_key' in f.definition)=0,false),
    'future_timestamp_guard',coalesce(position('d.posted_at <= now()' in f.definition)>0,false),
    'response_identity',coalesce(position('''viewer_user_id'',auth.uid()' in f.definition)>0 and position('''requested_agent_id'',p_agent_id' in f.definition)>0,false),
    'definition_md5',md5(f.definition)
  ) from cohort_function f)
) as release
